def subtract(a, b):
    def merge_intervals(intervals):
        """Merge overlapping/touching intervals and return sorted disjoint intervals."""
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [interval for interval in intervals if interval[0] < interval[1]]
        if not valid:
            return []

        valid.sort()

        # Merge overlapping and touching intervals
        merged = [valid[0]]
        for start, end in valid[1:]:
            last_start, last_end = merged[-1]
            if start <= last_end:
                # Overlapping or touching, merge them
                merged[-1] = [last_start, max(last_end, end)]
            else:
                # Non-overlapping, add as new interval
                merged.append([start, end])

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current = a_start

        # Find all b intervals that overlap with [a_start, a_end)
        for b_start, b_end in b_merged:
            # If b interval is completely before current position, skip
            if b_end <= current:
                continue

            # If b interval is completely after current position, we're done with this b
            if b_start >= a_end:
                break

            # If there's a gap between current and where b starts, add it to result
            if current < b_start:
                result.append([current, b_start])

            # Move current past this b interval
            current = max(current, b_end)

        # Add any remaining part of a after all b intervals
        if current < a_end:
            result.append([current, a_end])

    return result

